import type {ConfigField} from './configurationTypes';

type Section=ConfigField['section'];
const f=(key:string,label:string,kind:ConfigField['kind'],help:string,section:Section='configuration',extra:Partial<ConfigField>={}):ConfigField=>({key,label,kind,section,help,...extra});
const text=(k:string,l:string,h:string,section:Section='configuration')=>f(k,l,'text',h,section);
const select=(k:string,l:string,options:string[],h:string,section:Section='configuration')=>f(k,l,'select',h,section,{options});
const bool=(k:string,l:string,h:string,section:Section='configuration')=>f(k,l,'boolean',h,section);
const number=(k:string,l:string,unit:string,h:string,section:Section='configuration')=>f(k,l,'number',h,section,{min:0,unit});
const resource=(k:string,l:string,services:string[],h:string,section:Section='configuration')=>f(k,l,'resource',h,section,{resourceServices:services});
const table=(k:string,l:string,itemFields:ConfigField[],h:string,section:Section='configuration')=>f(k,l,'table',h,section,{itemFields});
const document=(k:string,l:string,kind:'json'|'yaml',h:string,section:Section='configuration')=>f(k,l,kind,h,section,{documentType:kind});
const role=(key='serviceRole',label='Service role')=>resource(key,label,['iam'],'Reference a role with the actions required by this service; deployment/build permissions are separate from workload runtime permissions.','permissions');
const when=(field:string,values:(string|number|boolean)[],entry:ConfigField):ConfigField=>({...entry,when:{field,values}});
const dimensions=()=>table('dimensions','Dimensions',[text('name','Name','Metric dimension name.'),text('value','Value','Dimension value without secrets or unbounded user identifiers.')],'Dimension combinations identify metric time series; do not accidentally create unbounded cardinality.','monitoring');
const env=()=>table('environmentVariables','Environment variables',[
 text('name','Name','Application/build variable name.'),select('type','Value source',['PLAINTEXT','PARAMETER_STORE','SECRETS_MANAGER'],'Secret stores require corresponding access permissions.'),text('value','Value or secret reference','Use fictional values or a secret reference. Never enter a real secret.')
],'Specify variable sources explicitly. Values included in frontend bundles are public.');
