 codebuild:{title:'CodeBuild buildspec reference',url:'https://docs.aws.amazon.com/codebuild/latest/userguide/build-spec-ref.html',objectives:['3.1','3.2']},
 codedeploy:{title:'CodeDeploy AppSpec reference',url:'https://docs.aws.amazon.com/codedeploy/latest/userguide/reference-appspec-file.html',objectives:['3.3','4.1']},
 codepipeline:{title:'CodePipeline stages and actions',url:'https://docs.aws.amazon.com/codepipeline/latest/userguide/pipelines.html',objectives:['3.1','3.2','3.3']},
 xray:{title:'X-Ray trace concepts',url:'https://docs.aws.amazon.com/xray/latest/devguide/xray-concepts.html',objectives:['4.1','4.2']},
 appconfig:{title:'AppConfig deployment strategies',url:'https://docs.aws.amazon.com/appconfig/latest/userguide/appconfig-creating-deployment-strategy.html',objectives:['3.1','3.3','4.1']},
