 'cloudwatch-logs':{title:'CloudWatch log groups and streams',url:'https://docs.aws.amazon.com/AmazonCloudWatch/latest/logs/Working-with-log-groups-and-streams.html',objectives:['2.2','4.1','4.2']},
 cli:{title:'AWS CLI settings and credential precedence',url:'https://docs.aws.amazon.com/cli/latest/userguide/cli-chap-configure.html',objectives:['1.1','2.1','3.1']},
 'systems-manager':{title:'Systems Manager Parameter Store',url:'https://docs.aws.amazon.com/systems-manager/latest/userguide/systems-manager-parameter-store.html',objectives:['2.2','3.1','4.1']},
